def pcaFeatureImportance(
  data: Dataset[Row],
  numComponents: Int,
  numClusters: Int,
  numIterationsBootstraps: Int
): Seq[(String, Double)] = {

  val vectorAssembler = new VectorAssembler(Array[string]())
    .setInputCols(Array[ technologies_grouped_name: String, annual_revenue_grouped_name: String, net_income_grouped_name: String, age_grouped_name: String, employees_count_grouped_name: String ] )
    .setOutputCol("features_vector")

  val pca = new PCA(numComponents).setInputCol("features_vector").setOutputCol("pca_features")

  val lr = new LogisticRegression()

  val pipeline = new Pipeline().setStages(Array(vectorAssembler, pca, lr))

  val dataBootstrapClusters: Seq[Cluster[_]] = getBootstrapClusters(data)

  val scores: Seq[(String, Double)] = (1 to numIterationsBootstraps).map { bootstrap =>
    val bootstrapDF: Dataset[Row] = dataBootstrapClusters.sample(true, numClusters, scala.util.Random)(spark)

    val pipelineModelBootstrap = pipeline.fit(bootstrapDF)

    // Calculer la performance de la sélection de caractéristiques sur le sous-ensemble bootstrap
    val featuresWeight = pipelineModelBootstrap.stages(1).asInstanceOf[PCA].explainedVariance.weightedBy(true)

    // Extraire les caractéristiques les plus importantes avec poids calculé
    val importance = pipelineModelBootstrap.stages(2).asInstanceOf[LogisticRegression].coefficients.map { (i, v) =>
      (i, featuresWeight(i))
    }.sortBy(-_._2).take(5)

    importance
  }.squeeze(_ UNION _)

  scores
}

// Exécution du pipeline de sélection de caractéristiques
