import org.apache.commons.math3.ml.clustering.Cluster
import org.apache.commons.math3.ml.clustering.ClusterCenters

def imputeByRegression(clusters: Array[Cluster[Array[Double]]], dependentIndexes: Set[Int]): Seq[(String, Array[Double])] = {
  clusters.map(cluster => {
    val clusterData = cluster.getPoints.map(point => point.toArray)
    val model = LinearRegression.newModel(clusterData.map(_(dependentIndexes.head)).toArray, clusterData.map(_.copyRange(dependentIndexes.tail:_*)): _*)
    val predictedValues = model.getModel.predict(clusterData.map(_(dependentIndexes.head)).toArray)
    (cluster.getCenter.getVector.getX, predictedValues)
  }) 
}
