   Voici un exemple de code C# Windows Forms qui prend en charge la capture vidéo en direct à partir de la caméra Axis Q6215-LE :

   ```csharp
   using System;
   using System.Drawing;
   using System.IO;
   using System.Linq;
   using System.Runtime.InteropServices;
   using System.Threading.Tasks;
   using Axis.VapiX;

   namespace VAPIX_AxisQ6215LE_CsharpExample
   {
       public partial class Form1 : Form
       {
           private string cameraIP = "172.16.0.150"; // Remplacer votre adresse IP de la caméra Axis Q6215-LE
           private IVideoEncoder cameraVideoEncoder;

           public Form1()
           {
               InitializeComponent();
           }

           private void Form1_Load(object sender, EventArgs e)
           {
               // Configuration de la caméra Axis Q6215-LE
               var videoSetup = new VideoSetup();
               var networkAddress = new NetworkAddress(cameraIP);
               videoSetup.Setup(networkAddress);
               videoSetup.StreamRTPPlaylist(true);
               videoSetup.SetImageCompressionQuality(90); // Réduire la taille du fichier de captation vidéo (facultatif)

               var videoMgmt = new VideoManagementProxy(videoSetup);
               cameraVideoEncoder = videoMgmt.RetrieveVideoEncoder();

               Task.Run(async () =>
               {
                   while (true)
                   {
                       var bitmap = await CaptureVideoFrame();
                       pcbImage.Invoke((MethodInvoker)delegate { pcbImage.Image = bitmap });
                       await Task.Delay(16); // Capturer une nouvelle image toutes les 1/60s en mode NTSC ou 1/50s en mode PAL
                   }
               });
           }

           private async Task.Bitmap CaptureVideoFrame()
           {
               try
               {
                   // Verrouillage et désactivation de la capture pour limiter le trafic réseau
                   cameraVideoEncoder.Lock();
                   cameraVideoEncoder.TurnOffStream();

                   // Capture d'une image vidéo en direct
                   var imageSize = new ImageSize(2592, 1520);
                   var imageHeader = new ImageHeader();
                   using (var image = cameraVideoEncoder.GetImage(imageSize, imageHeader))
                   {
                       var bitmap = new Bitmap(image.Width, image.Height, System.Drawing.Imaging.PixelFormat.Format24bppRgb);
                       BitmapData bmpData = bitmap.LockBits(new Rectangle(0, 0, bitmap.Width, bitmap.Height), ImageLockMode.WriteOnly, bitmap.PixelFormat);
                       Marshal.Copy(image.Data, bmpData.Scan0, 0, image.PayloadSize);
                       bitmap.UnlockBits(bmpData);

                       return bitmap;
                   }

                   cameraVideoEncoder.TurnOnStream();
                   cameraVideoEncoder.Unlock();
               }
               catch (Exception ex)
               {
                   MessageBox.Show("Erreur pendant la capture de l'image : " + ex.Message);
                   return null;
               }
           }

           private void btnStop_Click(object sender, EventArgs e)
           {
               Application.Exit();
           }
       }
   }
   ```

   Remplacez l'adresse IP de la caméra (variable `cameraIP`) par votre propre adresse IP de la caméra Axis Q6215-LE.

