La liste chaînée multiple utilise trois listes chaînées distinctes pour les opérations pop, push et seeSaw, respectivement :

1. La liste chaînée pour les opérations pop et push contiendra tous les éléments entiers,
2. La troisième liste chaînée va contenir des paires (élément + index du noeud dans la liste chaînée principale), à partir desquelles nous pouvons rapidement calculer la somme demandée par l'opération seeSaw.

Voici une possible implémentation de la structure de données :

```cpp
class IntQueue {
private:
    Node* head = nullptr;

    // Cree un nouveau noeud contenant le valeur donnee et ajout le dans la liste chainee pour les pop/push operations
    void pushNode(int value) {
        Node* newNode = new Node{value, size(), {nullptr, nullptr, nullptr}};
        newNode->next[0] = head;
        head = newNode;
    }

    // Supprime le premier noeud de la liste chaînée pour les pop/push operations
    void popNode() {
        Node* temp = head;
        head = head->next[0];
        delete temp;
    }

    // Retourne la taille courante de la liste chaînée pour les pop/push operations
    int size() const {
        Node* temp = head;
        int count = 0;
        while (temp) {
            count++;
            temp = temp->next[0];
        }
        return count;
    }

public:
    // Construit une nouvelle instance de l'objet dans le temps O(1)
    IntQueue() {}

    // Insere un élément entier dans la file d'attente en O(1)
    void push(int value) {
        pushNode(value);
    }

    // Supprime et retourne le premier élément entier de la file en O(1)
    int pop() {
        if (!head) {
            throw std::underflow_error("File vide");
        }
        int value = head->value;
        popNode();
        return value;
    }

    // Calcule la somme des éléments (plus leur index) nécessaire pour l'opération seeSaw en O(1)
    int seeSaw() const {
        int result = 0, index = 0;
        Node* current = head;
        while (current && current->next[2]) {
            Node* node = current->next[2];
            result += node->value + index;
            index += 2; // Incrementer l'index de deux à chaque fois qu'on trouve une paire (élément + index) dans la liste chaînée
            current = current->next[0];
            node = node->next[0];
        }
        return result;
    }

    // Retourne la taille actuelle de la file en O(1)
    int size() const {
        return size();
    }

    void clear() {
        while (head) {
            popNode();
        }
    }
