```python
class Node:
    def __init__(self, value, next=None):
        self.value = value
        self.next = next

class IntQueue:
    def __init__(self):
        self.head = None
        self.tail = None
        self.length = 0

    def enqueue(self, value):
        new_node = Node(value, None)
        if self.tail:
            self.tail.next = new_node
        else:
            self.head = new_node
        self.tail = new_node
        self.length += 1

    def dequeue(self):
        if not self.head:
            raise IndexError("Tente d'enlever d'une file vide")
        removed_value = self.head.value
        self.head = self.head.next
        self.length -= 1
        if not self.head:
            self.tail = None
        return removed_value

    def see_saw(self):
        if self.length < 2:
            raise ValueError("La file doit contenir au moins deux éléments pour effectuer cette opération")
        sum_tuples = [(self.head.value + 1) / self.tail.value, ]
        temp = self.head.next
        while temp:
            sum_tuples.append((temp.value + 1) / self.tail.next.value)
            self.tail = self.tail.next
            self.head = self.head.next
            temp = temp.next
        return sum(sum_tuples)

    def is_empty(self):
        return self.length == 0
