Suivez par la création d'une règle personnalisée ESLint basée sur `profile/vue/state-modifier`. Dans votre projet, vous pouvez créer un nouveau fichier `rules.yaml` dans le dossier `eslint-plugin-vue/profiles/` avec le contenu suivant :

```yaml
rules:
  vue/state-modifier:
    meta:
      type: problem
      docs:
        - description: Hook de cycle de vie mis à jour ne devrait pas modifier directement l'état du composant interne.
          url: https://vuejs.org/v2/style-guide/component-lifecycle-methods.html#Avoid-modifying-state-in-built-in-lifecycle-hooks
      fixable: "code"
      schema: []
    messages:
      warn:
        forbiddenStateModifier: "Ne modifiez pas directement l'état du composant interne dans ce gestionnaire de cycle de vie."
      fail:
        forbiddenStateModifier: "Ne pouvez pas modifier directement l'état du composant interne dans ce gestionnaire de cycle de vie."

    create: (context) ->
      hook = context.get JoiCustomData('hook')
      store = context.get JoiCustomData('store')
      modifiers = ['this.$set', 'this.$delete']

      # Utilisez la fonction `eslint/extend-rule` pour prendre en compte les options optionnelles
      # et ajoutez une erreur si les méthodes détectées appellent directement ou indirectement d'autres
      # méthodes modifiant l'état
      extendRule 'vue/state-modifier', (base) ->
        base.meta.deprecated = {
          identifier: '@typescript-eslint/no-modifiers'
          message: 'L\'ancienne règle vue/state-modifier est désactivée. Utilisez "@typescript-eslint/no-modifiers" pour vérifier la modification directe de l\'état interne.'
          url: 'https://github.com/typescript-eslint/typescript-eslint/tree/master/packages/eslint-plugin/docs/rules/no-modifiers.md'
        }

        base.meta.factory =
          (options) ->
            base.create
              meta: {...base.meta, ...options.meta}
              messages: {...base.meta.messages, ...options.messages}
              callProgram: (contextManager) ->
               .getService(contextManager̉, '@typescript-eslint/utils').promiseCallProgram(contextManager).then (program) ->
                  # Récupérez les fonctions de méthodes de l'AST
                  declarativeFunctionKeys = program.ast.program.body.filter(
                    ({type}) -> type in ['FunctionDeclaration', 'ArrowFunctionExpression'])
                    .flatMap(({body, id}) => if body?.body?.type === 'BlockStatement' && id?.name then body.body.filter(({type}) => type === 'ExpressionStatement')?.map(({expression: {callee, object}}) => {
                      return {callee, object}
                    }) : [])
                    .filter(({callee, object}) => [
                      ...Object.values(callee?.[Object.keys(callee)[0]] || {}).map((fn) => fn.name),
                      ...(object?.[Object.keys(object)[0]] || []).map((prop) => prop.name),
                    ].some((methodName) => modifiers.includes(methodName)))

                  # Testez si une fonction redéfinie dans la fonction du hook modifie directement l'état interne
                  declarativeFunctionKeys.forEach(({callee, object}) ->
                    if callee?.[Object.keys(callee)[0]]?.name in modifiers # Fonction directe modifiant l'état par appel direct
                      context.report({
                        node: callee.object,
                        message: options.messages.fail.forbiddenStateModifier,
                        fix: (fixer) ->
                          if hook?.name?.toString().startsWith('updated') # Attribution d'un nouvel écouteur d'événements est déjà interdite par la règle vue/no-modifying-event-listeners
                            return
                          if store?.propertyName?.name and store?.propertyName?.name.startsWith('$')
                            fixer.replaceTextRange(
                              [store?.propertyName?.range[0], store?.propertyName?.range[1]],
                              `$${store?.propertyName?.name.slice(1)}`
                            )
                          fixer.insertTextRange(
                            [
                              object.range[1],
                              object.range[1]
                            ],
                            `, computed: ${object.value}(\n  ...${object.value.params.map((param) =>
                              fixer.replaceTextRange(
                                param.range,
                                `${param.type === 'Identifier' ? 'data' : 'this'}.${param.name}`
                              )
                            )},\n)`
                          )
                      )
                    else if object && declarativeFunctionKeys.some(({callee: methodCallee}) => (
                      methodCallee?.[Object.keys(methodCallee)[0]]?.name in modifiers and
                      (callee?.[Object.keys(callee)[0]].arguments.some(({name: argName}) =>
                        declarativeFunctionKeys.some(({object, callee: methodCallee}) =>
